mapper.update:
update corgi_date
set `status` = #{date.status}
    where user_id = #{date.userId} order by id desc limit 1

update corgi_date_apply
set `status` = #{apply.status}
where id = #{apply.id}
  and `status` = 'apply'

mapper.select:
select

from corgi_date_apply a
where a.id = #{id}

select

from corgi_date_apply a
where approval_user_id = #{userId}

    and a.status = #{status}


    and a.ctime > #{startTime}


    and a.ctime <= #{endTime}

order by a.id desc

select count(1) count, min(ctime) startTime
from corgi_date_apply a
where approval_user_id = #{userId}

    and a.status = #{status}


    and a.ctime <= #{startTime}

select d.avatar
from corgi_date_apply a
left join corgi_user_detail d on d.user_id = a.apply_user_id
where approval_user_id = #{userId}
and d.avatar is not null
and d.avatar != ''

    and a.status = #{status}


    and a.ctime <= #{startTime}

limit 5

select

from corgi_date_apply a
where a.apply_user_id = #{userId}

    and a.status = #{status}

